void Request::Parse(Buffer& buf) {
    if (buf.ReadableSize() == 0) {
        throw std::invalid_argument("Buffer is empty");
    }

    // Parse status line
    std::string_view status_line = buf.ReadLine();
    size_t method_end = status_line.find(' ');
    if (method_end == std::string_view::npos) {
        throw std::invalid_argument("Invalid status line format");
    }
    method_ = http::MethodFromString(status_line.substr(0, method_end));

    size_t path_start = method_end + 1;
    size_t path_end = status_line.find(' ', path_start);
    if (path_end == std::string_view::npos) {
        throw std::invalid_argument("Invalid status line format");
    }
    path_ = status_line.substr(path_start, path_end - path_start);

    size_t version_start = path_end + 1;
    version_ = status_line.substr(version_start);

    // Parse headers
    while (true) {
        std::string_view header_line = buf.ReadLine();
        if (header_line.empty()) {
            break;
        }
        size_t colon_pos = header_line.find(':');
        if (colon_pos == std::string_view::npos) {
            throw std::invalid_argument("Invalid header format");
        }
        std::string key(header_line.substr(0, colon_pos));
        std::string value(header_line.substr(colon_pos + 1));
        headers_.emplace(std::move(key), std::move(value));
    }

    // Parse body (POST data)
    if (method_ == http::Method::Post) {
        size_t content_length = 0;
        auto it = headers_.find("Content-Length");
        if (it != headers_.end()) {
            content_length = std::stoi(it->second);
        }
        post_.Parse(buf.Read(content_length));
    }
}

std::optional<MappedReadOnlyFile> Response::Build(Buffer& buf, std::filesystem::path file, StatusCode& code) noexcept {
    file_path_ = root_dir_ / file;
    if (!std::filesystem::exists(file_path_)) {
        status_code_ = StatusCode::NotFound;
        AddPredefinedErrorContent(buf);
        return std::nullopt;
    }

    file_.Map(file_path_);
    if (!file_.IsValid()) {
        status_code_ = StatusCode::InternalServerError;
        AddPredefinedErrorContent(buf);
        return std::nullopt;
    }

    status_code_ = code;
    AddStatusLine(buf);
    AddHeaders(buf);
    AddMappedContent(buf);
    return file_;
}

