bool ConnectionImpl::Process() noexcept {
    if (read_buf_.ReadableSize() == 0) {
        keep_alive_ = false;
        return false;
    }

    Request request(read_buf_);
    request.Parse(read_buf_);

    Response response(root_dir_);
    StatusCode status_code = StatusCode::OK;
    auto file_opt = response.Build(write_buf_, std::filesystem::path(request.Path()), status_code);

    if (file_opt) {
        file_ = *file_opt;
    } else {
        status_code = StatusCode::NotFound;
    }

    keep_alive_ = request.KeepAlive();
    return true;
}

